def correct_bracketing_advanced(brackets: str):
    if ((len(brackets) % 2) != 0):
        return False
    stack = deque()
    openers = {'(', '[', '{'}
    closers_map = {')': '(', ']': '[', '}': '{'}
    for char in brackets:
        if (char in openers):
            stack.append(char)
        else:
            if (char in closers_map):
                if (not stack):
                    return False
                last_open = stack.pop()
                if (last_open != closers_map[char]):
                    return False
            else:
                return False
    return (not stack)

